ALTER TABLE public.products ALTER COLUMN shipping_returns_info SET DEFAULT 'Λάβετε ασφάλεια ή τα χρήματά σας πίσω! Όλες οι αγορές υποστηρίζονται από την εγγύηση επιστροφής χρημάτων 14 ημερών. Εάν για οποιονδήποτε λόγο δεν είστε ικανοποιημένοι – απλώς ενημερώστε μας και θα σας επιστρέψουμε τα χρήματά σας.';

ALTER TABLE public.products ALTER COLUMN warranty_info SET DEFAULT 'Πλήρης κάλυψη της συσκευής σας για 12 μήνες • Άμεση αντικατάσταση: Δεν τίθενται ερωτήσεις αντικατάσταση για κατασκευαστικά ελαττώματα• Εξειδικευμένη υποστήριξη: Η αφοσιωμένη ομάδα μας είναι εδώ για να σας βοηθήσει 24/7';

-- Update existing products that have NULL values
UPDATE public.products SET shipping_returns_info = 'Λάβετε ασφάλεια ή τα χρήματά σας πίσω! Όλες οι αγορές υποστηρίζονται από την εγγύηση επιστροφής χρημάτων 14 ημερών. Εάν για οποιονδήποτε λόγο δεν είστε ικανοποιημένοι – απλώς ενημερώστε μας και θα σας επιστρέψουμε τα χρήματά σας.' WHERE shipping_returns_info IS NULL;

UPDATE public.products SET warranty_info = 'Πλήρης κάλυψη της συσκευής σας για 12 μήνες • Άμεση αντικατάσταση: Δεν τίθενται ερωτήσεις αντικατάσταση για κατασκευαστικά ελαττώματα• Εξειδικευμένη υποστήριξη: Η αφοσιωμένη ομάδα μας είναι εδώ για να σας βοηθήσει 24/7' WHERE warranty_info IS NULL;